  [7871] = { "Sconfiggi gli invasori!", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Horde=Orda⟧, ottieni un ⟦Warsong Gulch Mark of Honor=Contrassegno d'Onore della Forra dei Cantaguerra⟧ e torna dalla sentinella Farsong al ⟦Silverwing Grove=Boschetto degli Alargentea⟧.", "Oltre questa galleria troverai un campo di lotta e tumulto, giovane {class}. L'⟦Horde=Orda⟧ continua a devastare la nostra foresta sacra, abbattendo i sempreverdi per alimentare le sue macchine da guerra.\n\nEntra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difendi la ⟦Silverwing Hold=Rocca di Alargentea⟧. Respingi le forze d'invasione dell'⟦Horde=Orda⟧!\n\nFallo, e otterrai un talismano al merito. Portami un tale talismano, {name}, e ti ricompenserò.", "Hai combattuto nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difeso la ⟦Silverwing Hold=Rocca di Alargentea⟧?", "Hai dimostrato il tuo valore nei nostri sforzi nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧. Continua a sostenere la causa e portami altri contrassegni d'onore. Fallo, e ti guadagnerai ancora di più la nostra fiducia.", 0x55520e44, 0xfeb46d9a, 0xd5134582, 0x71ff749c, 0xf9915c4e, "....." },
  [7872] = { "Sconfiggi gli invasori!", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Horde=Orda⟧, ottieni un ⟦Warsong Gulch Mark of Honor=Contrassegno d'Onore della Forra dei Cantaguerra⟧ e torna dalla sentinella Farsong al ⟦Silverwing Grove=Boschetto degli Alargentea⟧.", "Oltre questa galleria troverai un campo di lotta e tumulto, giovane {class}. L'⟦Horde=Orda⟧ continua a devastare la nostra foresta sacra, abbattendo i sempreverdi per alimentare le sue macchine da guerra.\n\nEntra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difendi la ⟦Silverwing Hold=Rocca di Alargentea⟧. Respingi le forze d'invasione dell'⟦Horde=Orda⟧!\n\nFallo, e otterrai un contrassegno d'onore. Portamelo, {name}, e ti ricompenserò.", "Hai combattuto nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difeso la ⟦Silverwing Hold=Rocca di Alargentea⟧?", "Hai dimostrato il tuo valore nei nostri sforzi nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧. Continua a sostenere la causa e portami altri contrassegni d'onore. Fallo, e ti guadagnerai ancora di più la nostra fiducia.", 0x55520e44, 0xfeb46d9a, 0x682b535e, 0x71ff749c, 0xf9915c4e, "....." },
  [7873] = { "Sconfiggi gli invasori!", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Horde=Orda⟧, ottieni un ⟦Warsong Gulch Mark of Honor=Contrassegno d'Onore della Forra dei Cantaguerra⟧ e torna dalla sentinella Farsong al ⟦Silverwing Grove=Boschetto degli Alargentea⟧.", "Oltre questa galleria troverai un campo di lotta e tumulto, giovane {class}. L'⟦Horde=Orda⟧ continua a devastare la nostra foresta sacra, abbattendo i sempreverdi per alimentare le sue macchine da guerra.\n\nEntra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difendi la ⟦Silverwing Hold=Rocca di Alargentea⟧. Respingi le forze d'invasione dell'⟦Horde=Orda⟧!\n\nFallo, e otterrai un contrassegno d'onore. Portamelo, {name}, e ti ricompenserò.", "Hai combattuto nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difeso la ⟦Silverwing Hold=Rocca di Alargentea⟧?", "Hai dimostrato il tuo valore nei nostri sforzi nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧. Continua a sostenere la causa e portami altri contrassegni d'onore. Fallo, e ti guadagnerai ancora di più la nostra fiducia.", 0x55520e44, 0xfeb46d9a, 0x682b535e, 0x71ff749c, 0xf9915c4e, "....." },
  [7874] = { "Domare gli usurpatori Alargentea", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Alliance=Alleanza⟧, ottieni un ⟦Warsong Gulch Mark of Honor=Contrassegno d'Onore della Forra dei Cantaguerra⟧ e portalo al capitano Shatterskull all'⟦Mor'shan Base Camp=Accampamento Mor'shan⟧.", "Le terre selvagge della foresta di ⟦Ashenvale=Valtetra⟧ cederanno alla potenza dell'⟦Horde=Orda⟧, {race}. Nulla di ciò che gli Alargentea dicono o fanno può fermare il nostro imperativo sovrano. Kalimdor appartiene all'⟦Horde=Orda⟧. Come osano cercare di impedirci di raccogliere ciò che è nostro di diritto!\n\nLascia che l'orgoglio ti gonfi il petto mentre stronchi i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ e ottieni un contrassegno d'onore dei ⟦Warsong=Cantaguerra⟧. Torna da me con un tale contrassegno, {name}, e sarai ricompensat<o/a>.", "Il sangue dei nostri nemici è un contrassegno d'onore. Ce l'hai un contrassegno del genere?", "<Il capitano Shatterskull ruggisce in trionfo.>\n\nQuanto ancora possono resistere? Quanta altra feccia dell'⟦Alliance=Alleanza⟧ deve perire per mano dell'⟦Horde=Orda⟧ prima che si ritirino? Solo il tempo lo dirà, {race}...", 0x636625b4, 0xc94c2293, 0x2eb6ef0c, 0xd1cff4b7, 0x160777a5, "....." },
  [7875] = { "Domare gli usurpatori Alargentea", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Alliance=Alleanza⟧, ottieni un Contrassegno d'Onore dei ⟦Warsong=Cantaguerra⟧ e portalo al capitano Shatterskull all'⟦Mor'shan Base Camp=Accampamento Mor'shan⟧.", "Le terre selvagge della foresta di ⟦Ashenvale=Valtetra⟧ cederanno alla potenza dell'⟦Horde=Orda⟧, {race}. Nulla di ciò che gli Alargentea dicono o fanno può fermare il nostro imperativo sovrano. Kalimdor appartiene all'⟦Horde=Orda⟧. Come osano cercare di impedirci di raccogliere ciò che è nostro di diritto!\n\nLascia che l'orgoglio ti gonfi il petto mentre stronchi i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ e ottieni un contrassegno d'onore dei ⟦Warsong=Cantaguerra⟧. Torna da me con un tale contrassegno, {name}, e sarai ricompensat<o/a>.", "Il sangue dei nostri nemici è un contrassegno d'onore. Ce l'hai un contrassegno del genere?", "<Il capitano Shatterskull ruggisce in trionfo.>\n\nQuanto ancora possono resistere? Quanta altra feccia dell'⟦Alliance=Alleanza⟧ deve perire per mano dell'⟦Horde=Orda⟧ prima che si ritirino? Solo il tempo lo dirà, {race}...", 0x636625b4, 0x3df29510, 0x2eb6ef0c, 0xd1cff4b7, 0x160777a5, "....." },
  [7876] = { "Domare gli usurpatori Alargentea", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Alliance=Alleanza⟧, ottieni un ⟦Warsong Gulch Mark of Honor=Contrassegno d'Onore della Forra dei Cantaguerra⟧ e portalo al capitano Shatterskull all'⟦Mor'shan Base Camp=Accampamento Mor'shan⟧.", "Le terre selvagge della foresta di ⟦Ashenvale=Valtetra⟧ cederanno alla potenza dell'⟦Horde=Orda⟧, {race}. Nulla di ciò che gli Alargentea dicono o fanno può fermare il nostro imperativo sovrano. Kalimdor appartiene all'⟦Horde=Orda⟧. Come osano cercare di impedirci di raccogliere ciò che è nostro di diritto!\n\nLascia che l'orgoglio ti gonfi il petto mentre stronchi i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ e ottieni un contrassegno d'onore. Torna da me con un tale contrassegno, {name}, e sarai ricompensat<o/a>.", "Il sangue dei nostri nemici è un contrassegno d'onore. Ce l'hai un contrassegno del genere?", "<Il capitano Shatterskull ruggisce in trionfo.>\n\nQuanto ancora possono resistere? Quanta altra feccia dell'⟦Alliance=Alleanza⟧ deve perire per mano dell'⟦Horde=Orda⟧ prima che si ritirino? Solo il tempo lo dirà, {race}...", 0x636625b4, 0xc94c2293, 0x2eb6b1fd, 0xd1cff4b7, 0x160777a5, "....." },
  [7946] = { "La progenie di Jubjub", nil, nil, "Sono così felice che Jubjub non sia più persa. Adora talmente la birra dei ⟦Dark Iron=Ferroscuro⟧ che quando l'ho finita... è scappata per trovarne altra!\n\nOra che Jubjub è tornata, voglio tutta la birra che riesco a procurarmi! Non voglio che scappi di nuovo!\n\nHai della birra dei ⟦Dark Iron=Ferroscuro⟧? Se ce l'hai, ti darò una delle uova di rana di Jubjub in cambio di un boccale...", "Grazie, {name}. Ecco il tuo uovo! Ci vorrà un po' prima che si schiuda, ma quando succederà avrai un fantastico animaletto!", 0xad05c1dd, nil, nil, 0x09b8849d, 0xb8311bf6, ".mm.." },
  [7961] = { "Wabbit biwbanti!", "Uccidi 5 conigli e torna da Jon LeCraft, vicino alla forgia sull'⟦Designer Island=Isola degli Sviluppatori⟧.", "Questi conigli si riproducono in modo incontrollabile. Bisogna fare qualcosa!\n\nAiutaci, {name}, sei la nostra unica speranza.", nil, nil, 0x26e1428c, 0x7c67e5a2, 0x62029839, nil, nil, "...mm" },
  [7962] = { "Pelli di Wabbit", "Porta 3 LeCrafty Rabbit Pelt a Jon LeCraft.", "Voglio pelli di LeCrafty Rabbit. Procuramene un po' dai LeCrafty Rabbit.\n\nÈ importante!", nil, nil, 0x1ebd053c, 0xfd9305aa, 0x7ff5eaf6, nil, nil, "...mm" },
})
